import heapq


def _dependency_solver(data, name_order, preference):
    packages = data["packages"]
    names = sorted(packages, reverse=(name_order == "descending"))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    best_vector = None
    best_install = None

    def visit(chosen, constraints, edges):
        nonlocal best_vector, best_install
        pending = [name for name in constraints if name not in chosen]
        if not pending:
            vector = tuple(chosen.get(name, -1) for name in names)
            if (best_vector is None or
                    (vector < best_vector if preference == "minimum" else vector > best_vector)):
                best_vector = vector
                best_install = dict(chosen)
            return

        name = min(pending)
        low, high = constraints[name]
        rows = [row for row in packages[name]
                if low <= row["version"] <= high
                and row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        for row in rows:
            version = row["version"]
            next_chosen = dict(chosen)
            next_chosen[name] = version
            next_constraints = dict(constraints)
            next_edges = {key: set(value) for key, value in edges.items()}
            next_edges.setdefault(name, set())
            valid = True
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                dep_low, dep_high = dep["min"], dep["max"]
                if target in next_constraints:
                    old_low, old_high = next_constraints[target]
                    dep_low = max(dep_low, old_low)
                    dep_high = min(dep_high, old_high)
                if dep_low > dep_high:
                    valid = False
                    break
                next_constraints[target] = (dep_low, dep_high)
                if target in next_chosen and not dep_low <= next_chosen[target] <= dep_high:
                    valid = False
                    break
                next_edges[name].add(target)
            if not valid:
                continue

            active, finished = set(), set()

            def acyclic(node):
                if node in active:
                    return False
                if node in finished:
                    return True
                active.add(node)
                for neighbor in next_edges.get(node, ()):
                    if not acyclic(neighbor):
                        return False
                active.remove(node)
                finished.add(node)
                return True

            if all(acyclic(node) for node in next_edges):
                visit(next_chosen, next_constraints, next_edges)

    constraints = {name: tuple(bounds) for name, bounds in data["roots"].items()}
    visit({}, constraints, {})
    if best_install is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_install}


